INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (111031, 10, "", "", 302, "", 13020023, "", "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", 11, "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (0, "", "", "", 302, "", 13020024, "", "", 91, "");
