INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (111031, 10, "", "", 302, "", 13020026, "", "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", 11, "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (0, "", "", "", 302, "", 13020027, "", 1, 91, "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (111031, 10, "", "", 302, "", 13020028, "", "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", 11, "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (0, "", "", "", 302, "", 13020029, "", 1, 91, "");
